const payload = $json.body ?? $json;
const headers = $json.headers ?? {};
const expectedSecret = typeof $env !== 'undefined' ? $env.N8N_WHATSAPP_REMINDER_WEBHOOK_SECRET : '';
const receivedSecret = headers['x-monfily-webhook-secret'] || headers['X-Monfily-Webhook-Secret'];
if (expectedSecret && receivedSecret !== expectedSecret) throw new Error('Invalid webhook secret.');

const to = payload.to || payload.variables?.whatsappTo;
const rawMessage = payload.reminder?.message || payload.variables?.message;
const message = String(rawMessage || '').normalize('NFC');
const evolution = payload.delivery?.evolution;
const requestedWaitSeconds = Number(payload.reminder?.sendAfterSeconds);
const requestedDelayMs = Number(payload.reminder?.delayMs);
const waitSeconds = Number.isFinite(requestedWaitSeconds)
  ? Math.max(0, requestedWaitSeconds)
  : Math.max(0, Math.round((Number.isFinite(requestedDelayMs) ? requestedDelayMs : 480000) / 1000));

if (!to) throw new Error('Missing WhatsApp destination number.');
if (!message) throw new Error('Missing WhatsApp message.');
if (!evolution?.apiUrl || !evolution?.instanceName || !evolution?.apiKey) {
  throw new Error('Missing Evolution delivery config. Configure EVOLUTION_API_URL and the country-specific EVOLUTION_*_INSTANCE_NAME / EVOLUTION_*_INSTANCE_TOKEN values in the Monfily API .env.');
}

const apiUrl = String(evolution.apiUrl).replace(/\/+$/, '');
const hostMatch = /^https?:\/\/([^/?#]+)/i.exec(apiUrl);
const host = hostMatch ? hostMatch[1].toLowerCase() : '';
if (!host || host === 'sua-evolution.com' || host === 'example.com' || host.includes('seudominio') || host.includes('seu-dominio')) {
  throw new Error('Invalid EVOLUTION_API_URL: replace the documentation placeholder with the real Evolution API URL in the Monfily API .env.');
}

const instanceName = encodeURIComponent(String(evolution.instanceName));
const delayMs = Number.isFinite(Number(evolution.delayMs)) ? Number(evolution.delayMs) : 1200;

return [{
  json: {
    to,
    message,
    waitSeconds,
    evolutionUrl: `${apiUrl}/message/sendText/${instanceName}`,
    evolutionApiKey: String(evolution.apiKey),
    evolutionDelayMs: delayMs,
    idempotencyKey: payload.idempotencyKey,
    language: payload.language,
    marketKey: payload.marketKey,
    reminderKind: payload.reminder?.kind,
    payload
  }
}];
